"use strict";
// Private independent acceptance harness. Evaluates only a manually reviewed
// pure leaf in a VM without filesystem/network/process globals. It neither
// executes worker tests nor changes worker/candidate files.
const fs = require("node:fs");
const vm = require("node:vm");
const crypto = require("node:crypto");
const assert = require("node:assert/strict");
const path = require("node:path");
const { createRequire } = require("node:module");
const [sourceFile, fixtureFile, targetRoot, rawTimeout = "5000"] = process.argv.slice(2);
if (!targetRoot) throw Error("usage: harness SOURCE_TS FIXTURE_JS TARGET_ROOT [VM_TIMEOUT_MS]");
const targetRequire = createRequire(path.resolve(targetRoot, "package.json"));
const ts = targetRequire("typescript");
const vmTimeoutMs = Number(rawTimeout);
if (!Number.isSafeInteger(vmTimeoutMs) || vmTimeoutMs < 10 || vmTimeoutMs > 10000) throw Error("invalid VM timeout");
if (!sourceFile || !fixtureFile) throw Error("source and independent fixture required");
function transpile(source, filename) {
  const result = ts.transpileModule(source, {fileName: filename, reportDiagnostics: true,
    compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}});
  if (result.diagnostics.some(d=>d.category===ts.DiagnosticCategory.Error)) throw Error("typescript syntax rejected");
  return result.outputText;
}
const engineSource=fs.readFileSync(path.resolve(targetRoot,"packages/engine/src/index.ts"),"utf8");
const engine={exports:{}};
const engineContext=vm.createContext(engine,{codeGeneration:{strings:false,wasm:false}});
vm.runInContext(transpile(engineSource,"trusted-engine-index.ts"),engineContext,{timeout:5000});
const source=fs.readFileSync(sourceFile,"utf8");
const fixture=fs.readFileSync(fixtureFile,"utf8");
let checks=0;
const context=vm.createContext({exports:{},
 require(spec){if(spec==="../index.js")return engine.exports;throw Error("unexpected module import");},
 countCheck(){checks++;},nodeAssert:assert,
},{codeGeneration:{strings:false,wasm:false}});
vm.runInContext("(function(exports, require){\n" + transpile(source,sourceFile) + "\n})(exports, require);",context,{timeout:vmTimeoutMs});
vm.runInContext(`
 function canon(v){if(Array.isArray(v))return v.map(canon);if(v&&typeof v==='object')return Object.fromEntries(Object.keys(v).sort().map(k=>[k,canon(v[k])]));return v;}
 function check(v,label){nodeAssert.ok(v,label);countCheck();}
 function same(a,b,label){nodeAssert.deepStrictEqual(canon(a),canon(b),label);countCheck();}
 function good(result){check(result&&result.ok===true,'valid frozen-contract input must succeed');return result.value;}
 function bad(result,code){check(result&&result.ok===false,'invalid/forbidden input must fail');if(code)same(result.error.code,code);return result.error;}
 `+fixture,context,{timeout:vmTimeoutMs});
console.log(JSON.stringify({kind:"independent_private_pure_leaf_acceptance",passed:true,checks,
 source_sha256:crypto.createHash("sha256").update(source).digest("hex"),
 fixture_sha256:crypto.createHash("sha256").update(fixture).digest("hex"),
 cloud_calls:0,model_calls:0,implementation_modified:false,module_scope_isolated:true,vm_timeout_ms:vmTimeoutMs}));

