export function fixtureProbe(input:unknown){ if(input===null||typeof input!=='object')return {ok:false,error:{code:'invalid-input'}};const d=Object.getOwnPropertyDescriptor(input,'value');if(!d||!('value' in d)||typeof d.value!=='number')return {ok:false,error:{code:'invalid-input'}};return {ok:true,value:{value:d.value,label:same(),tag:f}}; }
